-- Grammar and Structure (15 questions)
('q_bece_eng_2024_01', 'topic_bece_grammar', 'subj_bece_english', 'Choose the correct form: She ___ to school every day.', 'multiple_choice', '["A. go", "B. goes", "C. going", "D. gone"]', 'B', 'Third person singular (she) requires "goes" in simple present tense.', 'easy', 1, 60),
('q_bece_eng_2024_02', 'topic_bece_grammar', 'subj_bece_english', 'Which sentence is grammatically correct?', 'multiple_choice', '["A. He don''t like rice.", "B. He doesn''t likes rice.", "C. He doesn''t like rice.", "D. He not like rice."]', 'C', 'Correct structure: subject + doesn''t + base verb.', 'easy', 1, 60),
('q_bece_eng_2024_03', 'topic_bece_grammar', 'subj_bece_english', 'The plural of "child" is:', 'multiple_choice', '["A. childs", "B. childes", "C. children", "D. childrens"]', 'C', 'Child has an irregular plural form: children.', 'easy', 1, 60),
('q_bece_eng_2024_04', 'topic_bece_grammar', 'subj_bece_english', 'Choose the correct pronoun: ___ is my best friend.', 'multiple_choice', '["A. Him", "B. Her", "C. She", "D. Me"]', 'C', '"She" is a subject pronoun needed as the subject of the sentence.', 'easy', 1, 60),
('q_bece_eng_2024_05', 'topic_bece_grammar', 'subj_bece_english', 'Which word is an adverb?', 'multiple_choice', '["A. Quick", "B. Quickly", "C. Quicker", "D. Quickest"]', 'B', 'Adverbs often end in -ly. "Quickly" modifies verbs.', 'easy', 1, 60),
('q_bece_eng_2024_06', 'topic_bece_grammar', 'subj_bece_english', 'The past tense of "write" is:', 'multiple_choice', '["A. writed", "B. wrote", "C. written", "D. writing"]', 'B', 'Write is an irregular verb. Past tense is "wrote".', 'easy', 1, 60),
('q_bece_eng_2024_07', 'topic_bece_grammar', 'subj_bece_english', 'Choose the correct preposition: The book is ___ the table.', 'multiple_choice', '["A. in", "B. on", "C. at", "D. by"]', 'B', '"On" is used when something is on a surface.', 'easy', 1, 60),
('q_bece_eng_2024_08', 'topic_bece_grammar', 'subj_bece_english', 'Which is a compound sentence?', 'multiple_choice', '["A. I went home.", "B. I went home and ate dinner.", "C. Going home.", "D. The tall boy."]', 'B', 'A compound sentence has two independent clauses joined by a conjunction.', 'medium', 1, 90),
('q_bece_eng_2024_09', 'topic_bece_grammar', 'subj_bece_english', 'The comparative form of "good" is:', 'multiple_choice', '["A. gooder", "B. more good", "C. better", "D. best"]', 'C', '"Good" has an irregular comparative form: "better".', 'easy', 1, 60),
('q_bece_eng_2024_10', 'topic_bece_grammar', 'subj_bece_english', 'Choose the correct article: ___ apple a day keeps the doctor away.', 'multiple_choice', '["A. A", "B. An", "C. The", "D. No article"]', 'B', '"An" is used before words starting with vowel sounds.', 'easy', 1, 60),
('q_bece_eng_2024_11', 'topic_bece_grammar', 'subj_bece_english', 'Which sentence shows correct subject-verb agreement?', 'multiple_choice', '["A. The boys plays football.", "B. The boy play football.", "C. The boys play football.", "D. The boy playing football."]', 'C', 'Plural subject "boys" needs plural verb "play" (no -s).', 'medium', 1, 60),
('q_bece_eng_2024_12', 'topic_bece_grammar', 'subj_bece_english', 'Identify the verb in: "The children ran to school."', 'multiple_choice', '["A. children", "B. ran", "C. school", "D. The"]', 'B', '"Ran" is the verb showing the action.', 'easy', 1, 60),
('q_bece_eng_2024_13', 'topic_bece_grammar', 'subj_bece_english', 'The possessive form of "it" is:', 'multiple_choice', '["A. it''s", "B. its", "C. its''", "D. its''s"]', 'B', '"Its" (no apostrophe) is the possessive. "It''s" means "it is".', 'medium', 1, 60),
('q_bece_eng_2024_14', 'topic_bece_grammar', 'subj_bece_english', 'Which is an interrogative sentence?', 'multiple_choice', '["A. Close the door.", "B. What a beautiful day!", "C. Where are you going?", "D. She is reading."]', 'C', 'Interrogative sentences ask questions and end with ?.', 'easy', 1, 60),
('q_bece_eng_2024_15', 'topic_bece_grammar', 'subj_bece_english', 'Choose the correct tense: By next year, I ___ graduated.', 'multiple_choice', '["A. will have", "B. would", "C. have", "D. had"]', 'A', 'Future perfect tense: "will have" + past participle.', 'medium', 1, 90),

-- Vocabulary (10 questions)
('q_bece_eng_2024_16', 'topic_bece_vocabulary', 'subj_bece_english', 'The synonym of "happy" is:', 'multiple_choice', '["A. sad", "B. joyful", "C. angry", "D. tired"]', 'B', 'Joyful means the same as happy (feeling pleasure).', 'easy', 1, 60),
('q_bece_eng_2024_17', 'topic_bece_vocabulary', 'subj_bece_english', 'The antonym of "dark" is:', 'multiple_choice', '["A. black", "B. dim", "C. light", "D. shadow"]', 'C', 'Light is the opposite of dark.', 'easy', 1, 60),
('q_bece_eng_2024_18', 'topic_bece_vocabulary', 'subj_bece_english', 'Which word means "to make something better"?', 'multiple_choice', '["A. worsen", "B. improve", "C. destroy", "D. ignore"]', 'B', 'Improve means to make something better.', 'easy', 1, 60),
('q_bece_eng_2024_19', 'topic_bece_vocabulary', 'subj_bece_english', '"Enormous" means:', 'multiple_choice', '["A. tiny", "B. very large", "C. medium", "D. narrow"]', 'B', 'Enormous means very large or huge.', 'easy', 1, 60),
('q_bece_eng_2024_20', 'topic_bece_vocabulary', 'subj_bece_english', 'Choose the correctly spelled word:', 'multiple_choice', '["A. recieve", "B. receive", "C. receve", "D. receeve"]', 'B', 'The correct spelling follows "i before e except after c".', 'easy', 1, 60),
('q_bece_eng_2024_21', 'topic_bece_vocabulary', 'subj_bece_english', 'A "pedestrian" is someone who:', 'multiple_choice', '["A. drives a car", "B. rides a bicycle", "C. walks", "D. flies a plane"]', 'C', 'A pedestrian is a person who walks, especially in a city.', 'easy', 1, 60),
('q_bece_eng_2024_22', 'topic_bece_vocabulary', 'subj_bece_english', 'The word "nocturnal" relates to:', 'multiple_choice', '["A. day", "B. night", "C. morning", "D. evening"]', 'B', 'Nocturnal means active at night.', 'medium', 1, 60),
('q_bece_eng_2024_23', 'topic_bece_vocabulary', 'subj_bece_english', 'An "orphan" is a child who has lost their:', 'multiple_choice', '["A. toys", "B. friends", "C. parents", "D. school"]', 'C', 'An orphan is a child whose parents have died.', 'easy', 1, 60),
('q_bece_eng_2024_24', 'topic_bece_vocabulary', 'subj_bece_english', 'Which word is similar to "brave"?', 'multiple_choice', '["A. cowardly", "B. fearful", "C. courageous", "D. weak"]', 'C', 'Courageous means brave or willing to face danger.', 'easy', 1, 60),
('q_bece_eng_2024_25', 'topic_bece_vocabulary', 'subj_bece_english', '"Transparent" means:', 'multiple_choice', '["A. solid", "B. see-through", "C. opaque", "D. colored"]', 'B', 'Transparent means you can see through it clearly.', 'easy', 1, 60),

-- Reading Comprehension (10 questions)
('q_bece_eng_2024_26', 'topic_bece_comprehension', 'subj_bece_english', 'Read: "Kofi woke up early. He brushed his teeth and ate breakfast. Then he walked to school." What did Kofi do first?', 'multiple_choice', '["A. Ate breakfast", "B. Walked to school", "C. Woke up early", "D. Brushed his teeth"]', 'C', 'According to the passage, Kofi first woke up early.', 'easy', 1, 60),
('q_bece_eng_2024_27', 'topic_bece_comprehension', 'subj_bece_english', 'What is the main purpose of a dictionary?', 'multiple_choice', '["A. To tell stories", "B. To define words", "C. To show maps", "D. To list phone numbers"]', 'B', 'A dictionary defines words and shows their meanings.', 'easy', 1, 60),
('q_bece_eng_2024_28', 'topic_bece_comprehension', 'subj_bece_english', 'A "biography" is:', 'multiple_choice', '["A. a story about animals", "B. a story about someone''s life", "C. a made-up story", "D. a recipe book"]', 'B', 'A biography is an account of someone''s life written by another person.', 'easy', 1, 60),
('q_bece_eng_2024_29', 'topic_bece_comprehension', 'subj_bece_english', 'The heading of a letter tells the reader:', 'multiple_choice', '["A. the body of the letter", "B. the date and address", "C. the signature", "D. the closing"]', 'B', 'The heading contains the sender''s address and the date.', 'easy', 1, 60),
('q_bece_eng_2024_30', 'topic_bece_comprehension', 'subj_bece_english', 'Which type of writing aims to persuade the reader?', 'multiple_choice', '["A. Narrative", "B. Descriptive", "C. Argumentative", "D. Expository"]', 'C', 'Argumentative writing aims to convince or persuade the reader.', 'medium', 1, 90),
('q_bece_eng_2024_31', 'topic_bece_comprehension', 'subj_bece_english', 'In a story, the "setting" refers to:', 'multiple_choice', '["A. the characters", "B. the time and place", "C. the problem", "D. the ending"]', 'B', 'The setting is where and when the story takes place.', 'easy', 1, 60),
('q_bece_eng_2024_32', 'topic_bece_comprehension', 'subj_bece_english', 'A "conclusion" in an essay:', 'multiple_choice', '["A. introduces the topic", "B. gives examples", "C. summarizes main points", "D. asks questions"]', 'C', 'The conclusion summarizes and wraps up the main ideas.', 'easy', 1, 60),
('q_bece_eng_2024_33', 'topic_bece_comprehension', 'subj_bece_english', 'What does "Dear Sir/Madam" indicate in a letter?', 'multiple_choice', '["A. Informal letter", "B. Formal letter", "C. Friendly letter", "D. Thank you note"]', 'B', '"Dear Sir/Madam" is a formal salutation for official letters.', 'easy', 1, 60),
('q_bece_eng_2024_34', 'topic_bece_comprehension', 'subj_bece_english', 'The "moral" of a story is:', 'multiple_choice', '["A. the beginning", "B. the lesson learned", "C. the main character", "D. the title"]', 'B', 'The moral is the lesson or message of the story.', 'easy', 1, 60),
('q_bece_eng_2024_35', 'topic_bece_comprehension', 'subj_bece_english', 'What is a "simile"?', 'multiple_choice', '["A. A comparison using like or as", "B. A repeated sound", "C. An exaggeration", "D. A type of poem"]', 'A', 'A simile compares two things using "like" or "as".', 'medium', 1, 60),

