('q_bece_eng_2023_10', 'topic_bece_grammar', 'subj_bece_english', 'Choose the correct form: Neither Kofi nor Ama ___ present.', 'multiple_choice', '["A. are", "B. is", "C. were", "D. have been"]', 'B', 'Neither...nor takes a singular verb when subjects are singular.', 'medium', 1, 90),
('q_bece_eng_2023_11', 'topic_bece_grammar', 'subj_bece_english', 'An exclamatory sentence ends with:', 'multiple_choice', '["A. .", "B. ?", "C. !", "D. ,"]', 'C', 'Exclamatory sentences express strong emotion and end with !', 'easy', 1, 60),
