('q_bece_eng_2023_14', 'topic_bece_grammar', 'subj_bece_english', 'Which is correct?', 'multiple_choice', '["A. He have a car.", "B. He has a car.", "C. He having a car.", "D. He haves a car."]', 'B', 'Third person singular takes "has".', 'easy', 1, 60),
